/**
 * ISO-46001 regulation-table seed builder (Plan 3 Task 22, 2026-09-18).
 *
 * SR-1: every seeded cell and every `verbatim_quote` was read in this session
 * from the raw plain-text transcript `Desktop\Guidelines\_site_audit\ISO-46001\_46001_raw.txt`
 * (BS ISO 46001:2019 = ISO 46001:2019(E), First edition 2019-07; 1287 lines;
 * a raw TWO-COLUMN extraction — the `.pdf` is NOT a source). The spans live in
 * `regulation-tables-quotes-iso46001.ts` (generated by line range, never
 * retyped); the line range is in each span's name. The sibling
 * `_46001_layout.txt` was consulted ONLY to settle which printed cell pairs
 * with which (Table A.1: the sector ↔ area grouping; Table D.1: the sector ↔
 * indicator pairing) — it is never quoted as a row source. A plain-text
 * transcript is a VC-grade source → both tables ship
 * `verification_status: 'imported_unverified'` (controller rule: txt = VC).
 * Verified by `scripts/regulation-tables/verify-regulation-tables.ts iso46001 "<transcript>"`.
 * Emitted as `20260917102200_regulation_tables_seed_iso46001.sql` (no earlier
 * ISO-46001 table seed exists — nothing superseded).
 *
 * Edition: the title page prints "ISO 46001" / "First edition 2019-07"
 * (L29–L32); prod `standards.version` is "2019 (ISO 46001:2019, First edition,
 * 2019-07; BS ISO 46001:2019)" (read-only 2026-09-18) → token `'2019'`.
 *
 * The standard prints NO numeric value table (inventory §1 — confirmed: Annex C
 * prints formulae, Annex B prose scenarios). Its two tables are informative
 * catalogues:
 *
 *   TABLEA1 — Table A.1 "Areas in which water use can be monitored" (L899–L988,
 *   two pages): 8 industry sectors × their lettered water-use areas, 39 rows.
 *   The raw extraction interleaves the two columns ("(f) Toilet (a) Guestroom",
 *   L917). Pairing rule, settled by the layout file (L1851–L1929): every
 *   sector's area list starts at "(a)" and increments — a line "(f) Toilet"
 *   followed by "(a) Guestroom" ends sector 1 (a–f) and opens sector 2, so an
 *   area belongs to the sector whose letter sequence it continues (two "(f)"
 *   cells in one sector are impossible on a printed list). Each row's
 *   `verbatim_quote` is the raw line that prints the cell (shared by the two
 *   cells a merged raw line carries); the sector cell is asserted against the
 *   whole-table span. Sector 8 prints its name over two layout lines ("Offices
 *   or retail buildings, or any other building" / "not mentioned in items 1 to
 *   7", L1927–L1928 of the layout) interleaved with its two areas on raw L988 —
 *   both fragments are asserted, the seeded cell joins them.
 *
 *   TABLED1 — Table D.1 "Examples of business activity indicators for industry
 *   sectors" (L1192–L1216): the raw file prints the 24 sectors (L1194–L1200)
 *   and the 24 indicator cells (L1202–L1216) as two SEPARATE column dumps; the
 *   layout file's vertical alignment drifts after the first line (the sector
 *   column is printed one per line, the indicator column one per two lines:
 *   "Food processing" sits beside the third "Number of units produced",
 *   "Prisons" beside "Mass of washloads"), so it settles ONLY the first pair —
 *   "Wafer fabrication" ↔ "Number of units produced" (both column dumps begin
 *   with these cells; layout L2238 prints them on one line under the heads).
 *   Every other pairing is NOT seeded (brief rule; sign-off iso46001-U-1 …
 *   U-23 propose the print-order pairing for the owner's PDF check, SR-3).
 *   One row today; `industry_sector` (the created select_one driver) offers
 *   exactly the seeded keys (G-A3).
 */
import type { RegulationTable, RegulationRow } from './regulation-tables';
import { Q } from './regulation-tables-quotes-iso46001';

const STD = 'ISO-46001';
export const ISO46001_EDITION = '2019';
const ED = ISO46001_EDITION;
const STATUS = 'imported_unverified' as const; // VC source (raw txt); D.1 pairing unsettled beyond row 1 (U-1 … U-23)

/** Whitespace-collapsed containment: the raw extraction prints cells with runs of spaces / line breaks. */
export const collapse = (s: string): string => s.replace(/\s+/g, ' ').trim();
/** Build-time SR-1 guard: every seeded cell fragment must be printed inside the named span. */
function inSpan(quote: string, cell: string, where: string): void {
  if (!collapse(quote).includes(collapse(cell))) throw new Error(`${where}: cell "${cell}" is not inside its verbatim span`);
}

