/** The printed sector name (fragments joined) by token. */
export const TABLEA1_SECTOR_NAMES: Record<string, string> = Object.fromEntries(TABLEA1_SECTORS.map((s) => [s.token, s.printed.join(' ')]));
/** Distinct area descriptions in print order — the `significant_uses.activity` datalist (-04). */
export const TABLEA1_AREA_DATALIST: readonly string[] = [...new Set(TABLEA1_AREAS.map((a) => a.area))];

export function tableA1AsTable(): RegulationTable {
  const letters = 'abcdefg';
  const rows: RegulationRow[] = TABLEA1_AREAS.map((a, i) => {
    const s = TABLEA1_SECTORS.find((x) => x.token === a.sector);
    if (!s) throw new Error(`TABLEA1 ${a.sector}: unknown sector`);
    const where = `TABLEA1 ${a.sector} ${a.letter}`;
    inSpan(a.quote, `${a.letter} ${a.area}`, where);
    inSpan(Q.L899_988, `${s.no} ${s.printed[0]}`, `${where} sector`);
    for (const f of s.printed) inSpan(s.quote, f, `${where} sector fragment`);
    // the letter sequence restarts at (a) per sector and increments by one (the pairing rule)
    const prev = TABLEA1_AREAS[i - 1];
    const expected = prev && prev.sector === a.sector ? letters[letters.indexOf(prev.letter[1]) + 1] : 'a';
    if (a.letter !== `(${expected})`) throw new Error(`${where}: letter sequence broken (expected (${expected}))`);
    const key = `${a.sector}_${a.letter[1]}`;
    return {
      row_key: key, keys: { area: key }, group_label: s.printed.join(' '), label_de: `${a.letter} ${a.area}`, order_index: i,
      values: { sector_token: s.token, sector_no: s.no, sector: s.printed.join(' '), letter: a.letter, description: a.area },
      verbatim_quote: a.quote,
    };
  });
  return { standard_code: STD, edition: ED, table_code: 'TABLEA1', title_de: 'Tabelle A.1 — Bereiche, in denen die Wassernutzung überwacht werden kann (Industriesektor → Wassernutzungsbereiche)', clause_reference: 'Annex A, A.12, Table A.1', page_ref: null,
    key_columns: ['area'],
    value_columns: [
      { name: 'sector_token', type: 'enum', values: TABLEA1_SECTORS.map((s) => s.token) },
      { name: 'sector_no', type: 'string' },
      { name: 'sector', type: 'string' },
      { name: 'letter', type: 'string' },
      { name: 'description', type: 'string' },
    ],
    // L888: "Table A.1 indicates areas within business activities where water use can be significant, and in which
    // monitoring can be beneficial" — an informative catalogue (can), never a limit ⇒ anhaltswert.
    override_policy: 'anhaltswert',
    override_quote: Q.L888,
    verification_status: STATUS, rows };
}

// ---------------------------------------------------------------------------
// TABLED1 — Table D.1 (L1192–L1216): ONE settled row (see the header; U-1 … U-23 for the other 23)
// ---------------------------------------------------------------------------
type D1Row = { key: string; sector: string; indicator: string; quote: string };
export const TABLED1_ROWS: readonly D1Row[] = [
  // raw L1194 opens the sector column with "Wafer fabrication", raw L1202 opens the indicator column with
  // "Number of units produced"; layout L2238 prints both on the first line under the column heads (L2237).
  { key: 'wafer_fabrication', sector: 'Wafer fabrication', indicator: 'Number of units produced', quote: Q.L1194_1202 },
];
/** The 24 printed sectors of the D.1 sector column in print order (raw L1194–L1200) — NOT seeded beyond row 1; listed for the U-blocks and the seed test. */
export const TABLED1_SECTOR_COLUMN: readonly string[] = [
  'Wafer fabrication', 'Semiconductor', 'Electronics', 'Chemical and pharmaceutical', 'Food processing', 'Other manufacturing',
  'Mining', 'Pulp and paper', 'Wood', 'Power generation', 'Agriculture', 'Livestock', 'Incineration plant', 'Petrochemical/refinery',
  'Laundries', 'Tree nurseries', 'Data centres', 'Shipyards', 'Commercial/office buildings',
  'Retail', 'Institutions/schools', 'Hospitals', 'Hotels', 'Prisons',
];
/** The 24 printed indicator cells of the D.1 indicator column in print order (raw L1202–L1216) — NOT seeded beyond cell 1. */
export const TABLED1_INDICATOR_COLUMN: readonly string[] = [
  'Number of units produced', 'Number of units produced', 'Number of units produced',
  'Volume or mass of products', 'Volume or mass of products',
  'Volume, mass or number of units produced as relevant to the manufacturing activity',
  'Mass of ore produced', 'Mass or number of rolls produced', 'Amount of products produced', 'Energy produced',
  'Volume or mass of raw food products', 'Number of head of processed meat', 'Mass of waste processed',
  'Mass/volume of chemicals produced and/or mass/volume of throughput', 'Mass of washloads', 'Number of seedlings', 'IT equipment energy load',
  'Number of ships/oil rigs serviced, repaired or built',
  'Number of staff and visitors (calculate the full-time equivalent for visitors)',
  'Number of staff and visitors (calculate the full-time equivalent for visitors)',
  'Number of staff/students and visitors (calculate the full-time equivalent for visitors)',
  'Number of staff and occasional occupants (calculate the full-time equivalent for occasional occupants, e.g. inpatients/outpatients/ visitors)',
  'Number of occupied guestrooms',
  'Number of staff and inmates and visitors (calculate the full-time equivalent for visitors)',
];

export function tableD1AsTable(): RegulationTable {
  for (const s of TABLED1_SECTOR_COLUMN) inSpan(Q.L1194_1200, s, 'TABLED1 sector column');
  for (const c of TABLED1_INDICATOR_COLUMN) inSpan(Q.L1202_1216, c, 'TABLED1 indicator column');
  const rows: RegulationRow[] = TABLED1_ROWS.map((r, i) => {
    const where = `TABLED1 ${r.key}`;
    inSpan(r.quote, r.sector, `${where} sector`);
    inSpan(r.quote, r.indicator, `${where} indicator`);
    if (TABLED1_SECTOR_COLUMN[i] !== r.sector || TABLED1_INDICATOR_COLUMN[i] !== r.indicator) throw new Error(`${where}: not the first cells of both columns`);
    return {
      row_key: r.key, keys: { sector: r.key }, group_label: null, label_de: r.sector, order_index: i,
      values: { sector_label: r.sector, indicator_text: r.indicator },
      verbatim_quote: r.quote,
    };
  });
  return { standard_code: STD, edition: ED, table_code: 'TABLED1', title_de: 'Tabelle D.1 — Beispiele für Geschäftsaktivitäts-Indikatoren nach Industriesektor (nur die eine gesicherte Zeile; die übrigen 23 Zuordnungen sind iso46001-U-1 … U-23)', clause_reference: 'Annex D, Table D.1', page_ref: null,
    key_columns: ['sector'],
    value_columns: [
      { name: 'sector_label', type: 'string' },
      { name: 'indicator_text', type: 'string' },
    ],
    // L1192 "Examples of business activity indicators" + §6.2.5 L546 "identify specific business activity indicator(s)
    // appropriate" — examples the organization adapts ⇒ anhaltswert (the hint is overridable / typeable).
    override_policy: 'anhaltswert',
    override_quote: `${Q.L1192} — ${Q.L545_546}`,
    verification_status: STATUS, rows };
}

/** The live ISO-46001 set (two informative catalogues). */
export function iso46001SeedTables(): RegulationTable[] {
  return [tableA1AsTable(), tableD1AsTable()];
}
